create table if not exists company_profile (id bigint not null auto_increment comment 'company primary key', company_code varchar(64) not null comment 'company code', company_name varchar(128) not null comment 'company name', created_at datetime(3) not null default current_timestamp(3) comment 'created time', updated_at datetime(3) not null default current_timestamp(3) on update current_timestamp(3) comment 'updated time', primary key(id), unique key uk_company_code(company_code)) engine=InnoDB default charset=utf8mb4 comment='company profile';
create table if not exists department (id bigint not null auto_increment comment 'department primary key', parent_id bigint comment 'parent department id', code varchar(64) not null comment 'department code', name varchar(128) not null comment 'department name', status varchar(32) not null default 'ACTIVE' comment 'status', created_at datetime(3) not null default current_timestamp(3) comment 'created time', updated_at datetime(3) not null default current_timestamp(3) on update current_timestamp(3) comment 'updated time', created_by varchar(128) comment 'creator name', updated_by varchar(128) comment 'updater name', deleted_by varchar(128) comment 'deleter name', primary key(id), unique key uk_department_code(code)) engine=InnoDB default charset=utf8mb4 comment='department';
create table if not exists job_grade (id bigint not null auto_increment comment 'job grade primary key', code varchar(64) not null comment 'job grade code', name varchar(128) not null comment 'job grade name', level_value int comment 'level value', status varchar(32) not null default 'ACTIVE' comment 'status', primary key(id), unique key uk_job_grade_code(code)) engine=InnoDB default charset=utf8mb4 comment='job grade';
create table if not exists employee (id bigint not null auto_increment comment 'employee primary key', employee_no varchar(32) not null comment 'employee number', display_name varchar(128) not null comment 'display name', internal_mobile varchar(32) comment 'internal mobile', internal_email varchar(256) comment 'internal email', status varchar(32) not null default 'ACTIVE' comment 'status', primary_department_id bigint comment 'primary department id', job_grade_id bigint comment 'job grade id', created_at datetime(3) not null default current_timestamp(3) comment 'created time', updated_at datetime(3) not null default current_timestamp(3) on update current_timestamp(3) comment 'updated time', created_by varchar(128) comment 'creator name', updated_by varchar(128) comment 'updater name', deleted_by varchar(128) comment 'deleter name', primary key(id), unique key uk_employee_no(employee_no)) engine=InnoDB default charset=utf8mb4 comment='employee';

